from fastapi import APIRouter, Body, Depends

from modules.agents import agents_sp, all_agents_sp, one_agents_sp
from security.session_tokens import require_platform_admin_session, require_staff_session_or_worker_key

# Generated by posgmo-factory (PRD tests/prd_agent.json); guards added by hand.
# Catalog writes: admin of SmartLoans (companyId 1008) only. Reads: any POS staff
# session, or X-Worker-Key (LoanAgents_SmartLoans).
router = APIRouter()

with open("./docs_description/agents.txt", "r", encoding="utf-8") as file:
    agents_docstring = file.read()
with open("./docs_description/agents_all.txt", "r", encoding="utf-8") as file:
    agents_all_docstring = file.read()
with open("./docs_description/agents_one.txt", "r", encoding="utf-8") as file:
    agents_one_docstring = file.read()


@router.post("/agents", summary="agents: create / update / retire (SmartLoans admin)",
             description=agents_docstring, dependencies=[Depends(require_platform_admin_session)])
def agents(json_file: dict = Body(...)):
    return agents_sp(json_file)


@router.post("/all_agents", summary="all agents", description=agents_all_docstring,
             dependencies=[Depends(require_staff_session_or_worker_key)])
def all_agents(json_file: dict = Body(...)):
    return all_agents_sp(json_file)


@router.post("/one_agents", summary="one agent (by agentId or agentKey)", description=agents_one_docstring,
             dependencies=[Depends(require_staff_session_or_worker_key)])
def one_agents(json_file: dict = Body(...)):
    return one_agents_sp(json_file)
